import json, os
d='/tmp/xwatch/cand'
print('files', os.listdir(d))
for fn in sorted(os.listdir(d)):
    p=os.path.join(d,fn)
    try:
        j=json.load(open(p))
    except Exception as e:
        print(fn, 'PARSE', e)
        continue
    code=j.get('code')
    u=j.get('user') or {}
    v=u.get('verification') or {}
    print(f"{fn[:-5]:20} code={code} screen={u.get('screen_name')} name={u.get('name')!r} fol={u.get('followers')} tweets={u.get('tweets')} ver={v.get('verified')} type={v.get('type')}")
