python3 << 'PY'
import json, urllib.request, urllib.error, time
handles = [
"DeItaone","WalterBloomberg","LiveSquawk","unusual_whales","zabormetrics",
"CNBCOvertime","jimcramer","CarterBWorth","chaikinadvisor","StockMKTNewz",
"guraborisov","markminervini","WillMeade","TrendSpider","OptionsPlay","Stocktwits","MarketRebels","traborisov","IncredibleTrade","ripaborisov",
]
for h in handles:
    url = f"https://api.fxtwitter.com/{h}"
    try:
        req = urllib.request.Request(url, headers={"User-Agent":"Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=15) as r:
            data = json.loads(r.read().decode())
        u = data.get("user") or {}
        v = u.get("verification") or {}
        print(f"{h}\tOK\tverified={v.get('verified')}\ttype={v.get('type')}\tname={u.get('name')}\tfollowers={u.get('followers')}\ttweets={u.get('tweets')}")
    except urllib.error.HTTPError as e:
        body = e.read().decode(errors='ignore')[:200]
        print(f"{h}\tHTTP{e.code}\t{body}")
    except Exception as e:
        print(f"{h}\tERR\t{e}")
    time.sleep(0.15)
